  "After your password, you'll also type a 6-digit code from your phone or inbox — so someone who learns your password still can't get in.": "Après votre mot de passe, vous saisirez aussi un code à 6 chiffres reçu sur votre téléphone ou par e-mail — ainsi, quelqu'un qui connaît votre mot de passe ne peut toujours pas entrer.",
