  "All the tasks you can see at {company}: who is doing what, what is late and what is waiting for a review. Press a number to show only those tasks.": "Toutes les tâches que vous pouvez voir chez {company} : qui fait quoi, ce qui est en retard et ce qui attend une vérification. Appuyez sur un chiffre pour n'afficher que ces tâches.",
  "All the tasks you can see: who is doing what, what is late and what is waiting for a review. Press a number to show only those tasks.": "Toutes les tâches que vous pouvez voir : qui fait quoi, ce qui est en retard et ce qui attend une vérification. Appuyez sur un chiffre pour n'afficher que ces tâches.",
