  "Approved · to pay out": "Approuvé · à rembourser",
  "Approved and paid claims over the last 90 days, by category. Press one to show those claims.": "Demandes approuvées et payées des 90 derniers jours, par catégorie. Appuyez sur une catégorie pour afficher ces demandes.",
  "Approved and paid expense claims dated in the period, plus payroll cost: gross pay and the employer's SSNIT for runs approved or paid with a pay date in the period.": "Notes de frais approuvées et payées datées dans la période, plus le coût de la paie : salaire brut et SSNIT employeur des cycles approuvés ou payés dont la date de paiement tombe dans la période.",
  "Approved and paid runs over the last six months, by the month their period ends. Deductions are PAYE plus SSNIT from staff and employer.": "Cycles approuvés et payés des six derniers mois, selon le mois de fin de période. Les retenues comprennent la PAYE et la SSNIT salarié et employeur.",
  "Approved by": "Approuvé par",
