  "Approved expense claims by the day they were spent, and payroll: gross pay plus the employer's SSNIT for runs approved or paid, by pay date.": "Notes de frais approuvées selon le jour de la dépense, et paie : salaire brut plus SSNIT employeur des cycles approuvés ou payés, selon la date de paiement.",
