  "As on the stock sheet": "Comme sur la fiche de stock",
  "as terminated and disables their login. Their history (attendance, leave, tasks, documents) is kept for records — this does not permanently erase them.": "comme sorti(e) des effectifs et désactive son accès. Son historique (pointages, congés, tâches, documents) est conservé à titre d'archive — cette action ne l'efface pas définitivement.",
  "Ask about attendance, stock, sales, approvals…": "Posez une question sur les pointages, le stock, les ventes, les approbations…",
  "Ask about the company in plain words. It answers only from what your role can see, and when you ask it to do something it prepares it — nothing happens until you press Confirm. Press a number to go to it.": "Posez vos questions sur l'entreprise avec des mots simples. Il ne répond qu'à partir de ce que votre rôle peut voir, et quand vous lui demandez de faire quelque chose, il le prépare — rien ne se passe tant que vous n'appuyez pas sur Confirmer. Appuyez sur un chiffre pour y aller.",
  "Ask for something to be bought and follow it: approved, ordered, received. You get a notification at each step.": "Demandez un achat et suivez-le : approuvé, commandé, reçu. Vous êtes prévenu à chaque étape.",
  "Ask for time off and follow your requests. Days are working days: Sundays and public holidays are not counted.": "Demandez des congés et suivez vos demandes. Les jours sont des jours ouvrés : les dimanches et jours fériés ne comptent pas.",
  "Ask for time off, decide on your team's requests and see who is away, for {scope}. Days are working days: Sundays and public holidays are not counted. Press a number to show only those requests.": "Demandez des congés, décidez des demandes de votre équipe et voyez qui est absent, pour {scope}. Les jours sont des jours ouvrés : les dimanches et jours fériés ne comptent pas. Appuyez sur un chiffre pour n'afficher que ces demandes.",
  "Ask in your own words, in English, French or Chinese. It looks things up before answering and never changes anything without your Confirm.": "Posez vos questions avec vos mots, en anglais, en français ou en chinois. Il vérifie avant de répondre et ne modifie jamais rien sans votre confirmation.",
  "Ask people to confirm they have read it": "Demander aux personnes de confirmer leur lecture",
  "Ask to buy 20 bags of cement for the workshop.": "Demande l'achat de 20 sacs de ciment pour l'atelier.",
  "Ask to buy something": "Demander un achat",
