  "Find the mailbox's outgoing (SMTP) server. Hostinger email: smtp.hostinger.com, port 465. Google Workspace or Gmail: smtp.gmail.com, port 465, with an app password.": "Trouvez le serveur sortant (SMTP) de la boîte mail. E-mail Hostinger : smtp.hostinger.com, port 465. Google Workspace ou Gmail : smtp.gmail.com, port 465, avec un mot de passe d'application.",
