  "Followers, reach and messages for each company are on the social & campaign tracker.": "Les abonnés, la portée et les messages de chaque société se trouvent dans le suivi des réseaux sociaux et campagnes.",
  "Food": "Cuisine",
  "Food and supplies worth {amount} on the shelves. In the last 30 days: {bought} bought, {wasted} thrown away.": "Aliments et fournitures en rayon : {amount}. Ces 30 derniers jours : {bought} achetés, {wasted} jetés.",
  "for {amount}": "pour {amount}",
