  "Ghana uses GMT all year (Africa/Accra).": "Le Ghana est à l'heure GMT toute l'année (Africa/Accra).",
  "Give {amount} change": "Rendez {amount} de monnaie",
  "Give it a table or a name so anyone on the till can find it again and pay it later.": "Attribuez-lui une table ou un nom pour que chacun à la caisse puisse la retrouver et l'encaisser plus tard.",
