  "Granted {granted} new balance record(s) for {year}, across {employees} active employee(s) and {types} leave type(s).": "{granted} nouveau(x) solde(s) attribué(s) pour {year}, pour {employees} employé(s) actif(s) et {types} type(s) de congé.",
  "Granting…": "Attribution…",
  "Grey figures are worked out. A line not saved yet shows what it would be if nothing moved.": "Les chiffres en gris sont calculés. Une ligne non enregistrée montre ce qu'elle serait si rien n'avait bougé.",
