  "Hours the asset could not be used because of the work.": "Les heures pendant lesquelles le bien n'a pas pu être utilisé à cause du travail.",
  "How": "Comment",
  "How {company} did over {period}: what was invoiced and collected, what is still owed, and what went out on expense claims and payroll.": "Les résultats de {company} sur {period} : ce qui a été facturé et encaissé, ce qui reste dû, et ce qui est sorti en notes de frais et en paie.",
  "How clients pay": "Comment les clients paient",
  "How guests paid": "Comment les clients ont payé",
  "How it prints": "Rendu imprimé",
  "How it signs in": "Connexion",
  "How late": "Retard",
  "How late the money is": "Retard des paiements",
  "How late the money owed is": "Ancienneté des sommes dues",
  "How long": "Durée",
  "How long what is left lasts at the rate it was used over the last 30 days.": "Combien de temps dure le reste au rythme d'utilisation des 30 derniers jours.",
  "How many": "Combien",
  "How many are there?": "Combien y en a-t-il ?",
  "How many clients are at each stage. Press one to show only those.": "Combien de clients à chaque étape. Appuyez sur une étape pour n'afficher que ceux-là.",
  "How many customers are at each stage. The aim is to move people along, from lead to active and VIP.": "Combien de clients à chaque étape. L'objectif est de les faire avancer, de piste à actif puis VIP.",
  "How many days a new quotation stays open. After that it expires if the client hasn't answered.": "Nombre de jours pendant lesquels un nouveau devis reste ouvert. Ensuite, il expire si le client n'a pas répondu.",
  "How many days after issue a new invoice falls due. After that it shows as overdue.": "Nombre de jours après l'émission avant l'échéance d'une nouvelle facture. Ensuite, elle apparaît en retard.",
  "How many people are in each group. Press one to see its people.": "Le nombre de personnes dans chaque groupe. Appuyez sur un groupe pour voir ses membres.",
  "How many posts went out each day. Steady posting usually brings steady growth.": "Combien de publications sont parues chaque jour. Publier régulièrement apporte généralement une croissance régulière.",
  "How many times posts published in this period were seen.": "Nombre de fois où les publications de cette période ont été vues.",
  "How many times posts were seen: views on TikTok and YouTube, page views on the website, reach on Facebook and Instagram.": "Combien de fois les publications ont été vues : vues sur TikTok et YouTube, pages vues sur le site, portée sur Facebook et Instagram.",
  "How many?": "Combien ?",
  "How much": "Combien",
  "How much came in": "Quantité reçue",
  "How much is going out": "Quantité qui sort",
  "How much is on the shelf": "Quantité en rayon",
  "How much more (+) or less (−) a group took than in the month before, in cedis.": "Combien un groupe a encaissé de plus (+) ou de moins (−) que le mois précédent, en cedis.",
  "How much of the time between the start date and the deadline has passed.": "La part du temps écoulé entre la date de début et l'échéance.",
  "How much product one unit of bamboo gives, for example 2 planks per kg.": "Ce que donne une unité de bambou, par exemple 2 planches par kg.",
  "How often": "Fréquence",
  "How often posts were seen, by the day they were published: views on TikTok and YouTube, page views on the website.": "Combien de fois les publications ont été vues, selon leur jour de parution : vues sur TikTok et YouTube, pages vues sur le site.",
  "How people pay": "Comment on paie",
  "How someone is employed. \"By day\" means they are paid a daily rate for the days they work.": "Le type d'emploi. « À la journée » signifie qu'on est payé un tarif journalier pour les jours travaillés.",
  "How the company is named on documents and screens.": "Comment l'entreprise est nommée sur les documents et les écrans.",
  "How the money came in": "Comment l'argent est rentré",
  "How the restaurant is selling, what is on the menu, the food and supplies in stock, and whether the cash drawers add up. Sales come from the till. Press a number to go to it.": "Comment le restaurant vend, ce qu'il y a au menu, les aliments et fournitures en stock, et si les caisses sont justes. Les ventes viennent de la caisse. Appuyez sur un chiffre pour y aller.",
  "How this company is doing on social media and its website: who follows it, who sees its posts, and who is waiting for an answer.": "Comment se porte cette société sur les réseaux sociaux et son site : qui la suit, qui voit ses publications et qui attend une réponse.",
  "How to pay": "Comment payer",
  "How water and power are charged: paid by the tenant to the provider, read off a sub-meter, a fixed charge, or a share of the building's bill.": "Comment l'eau et l'électricité sont facturées : payées par le locataire au fournisseur, relevées sur un sous-compteur, forfait, ou part de la facture de l'immeuble.",
  "I've saved them": "Je les ai enregistrés",
  "IAM & Admin → Service accounts → Create service account (e.g. \"bamboo-os\"). Open it → Keys → Add key → Create new key → JSON. A .json file downloads.": "IAM et administration → Comptes de service → Créer un compte de service (par ex. « bamboo-os »). Ouvrez-le → Clés → Ajouter une clé → Créer une clé → JSON. Un fichier .json est téléchargé.",
  "ID": "Matricule",
  "ID — back": "Pièce d'identité — verso",
  "ID — front": "Pièce d'identité — recto",
  "ID & passport": "Pièce d'identité et passeport",
  "ID docs": "Pièces d'identité",
  "ID documents —": "Pièces d'identité —",
  "ID number": "Numéro de pièce d'identité",
  "ID type": "Type de pièce d'identité",
  "If {email} has an account, we've emailed a code to it. It works for {n} minutes.": "Si {email} a un compte, nous lui avons envoyé un code par e-mail. Il est valable {n} minutes.",
  "If {email} has an account, we've texted a code to the phone on it. It works for {n} minutes.": "Si {email} a un compte, nous avons envoyé un code par SMS au téléphone associé. Il est valable {n} minutes.",
  "If the unit's fixed utility fee was already included in the booking price, don't add it again here.": "Si le forfait de services du local est déjà inclus dans le prix de la réservation, ne l'ajoutez pas ici.",
  "If you left at a different time, tell your supervisor so they can correct it. Remember to clock out at the end of every shift.": "Si vous êtes parti à une autre heure, prévenez votre responsable pour qu'il la corrige. Pensez à pointer la sortie à la fin de chaque poste.",
  "If you lose your phone, each of these signs you in once instead of the code from the app. Keep them somewhere safe — they won't be shown again.": "Si vous perdez votre téléphone, chacun de ces codes vous connecte une fois à la place du code de l'application. Gardez-les en lieu sûr — ils ne seront plus affichés.",
