  "In {base}. An invoice in another currency shows on its own record and in the Invoices list, but isn't added into these totals.": "En {base}. Une facture dans une autre devise figure sur sa propre fiche et dans la liste des factures, mais n'est pas ajoutée à ces totaux.",
