  "Money": "Argent",
  "Money a client paid against one invoice. Payments are recorded from the Invoices page.": "Argent payé par un client sur une facture. Les paiements s'enregistrent depuis la page Factures.",
  "money asked for": "montant demandé",
  "Money collected less expense claims and payroll cost, in the base currency. It leaves out purchases and other costs, so it isn't profit — see Financial reports for that.": "L'argent encaissé moins les notes de frais et le coût de la paie, dans la devise de base. Les achats et autres coûts n'y figurent pas : ce n'est donc pas un bénéfice — voir les rapports financiers pour cela.",
  "Money in": "Entrées",
  "Money in against money out": "Entrées face aux sorties",
  "Money in and money out, by month": "Entrées et sorties d'argent, par mois",
  "Money on record between us and the supplier, with the story in the IOU notes.": "L'argent enregistré entre nous et le fournisseur, avec l'explication dans les notes.",
  "Money out": "Sorties",
  "Money someone spent for the business and asks to have paid back, with a photo of the receipt.": "L'argent qu'une personne a dépensé pour l'entreprise et dont elle demande le remboursement, avec une photo du justificatif.",
  "Money staff spent for the business and are claiming back: what waits for a decision, what is approved but not paid out, and where the money goes. Press a number to show only those.": "L'argent dépensé par le personnel pour l'entreprise et dont il demande le remboursement : ce qui attend une décision, ce qui est approuvé mais non remboursé, et où va l'argent. Appuyez sur un chiffre pour n'afficher que celles-ci.",
  "Money that actually moved in the period: payments and till sales in; expense claims paid out, pay runs marked paid and purchases received out. What is approved but not paid is shown separately.": "L'argent réellement mouvementé sur la période : paiements et ventes en caisse en entrée ; notes de frais remboursées, cycles de paie marqués payés et achats reçus en sortie. Ce qui est approuvé mais non payé est présenté à part.",
  "Money you spent for the business and are claiming back: send a claim with a photo of the receipt and follow it until it is paid.": "L'argent que vous avez dépensé pour l'entreprise et dont vous demandez le remboursement : envoyez une demande avec une photo du justificatif et suivez-la jusqu'au paiement.",
