  "News and notices for staff. New ones are marked; if an announcement asks you to confirm you have read it, press \"Got it\".": "Actualités et avis pour le personnel. Les nouvelles sont signalées ; si une annonce vous demande de confirmer sa lecture, appuyez sur « C'est noté ».",
