  "Nothing is uploaded or stored except the face measurements captured right now — no photo is kept. You'll be asked to look at your camera and slowly turn/tilt your head through a few angles, about 10 seconds in total.": "Rien n'est téléversé ni conservé hormis les mesures du visage relevées sur le moment — aucune photo n'est gardée. Il vous sera demandé de regarder votre caméra et de tourner ou incliner lentement la tête selon quelques angles, environ 10 secondes au total.",
  "Nothing is waiting for you. Every change it prepared has been decided.": "Rien ne vous attend. Chaque modification préparée a été tranchée.",
  "Nothing is waiting too long and nothing is late.": "Rien n'attend trop longtemps et rien n'est en retard.",
  "Nothing is waiting, everything approved is paid out, and every claim has its receipt.": "Rien n'est en attente, tout ce qui est approuvé est remboursé et chaque demande a son justificatif.",
