  "Opening…": "Ouverture…",
  "Opens on their own phone and walks them through the same camera steps — no need to hand them this device. The link only works once and expires on its own.": "S'ouvre sur leur propre téléphone et les guide à travers les mêmes étapes devant la caméra — inutile de leur tendre cet appareil. Le lien ne fonctionne qu'une fois et expire de lui-même.",
  "Opens WhatsApp in the person's chat with the reminder and a link to the bill already typed. You press send.": "Ouvre WhatsApp dans la conversation de la personne, avec la relance et un lien vers la facture déjà saisis. Vous appuyez sur envoyer.",
  "Operations": "Opérations",
  "optional": "facultatif",
  "Optional": "Facultatif",
  "Optional for approval, expected for a rejection.": "Facultatif pour une approbation, attendu pour un refus.",
  "Optional words sent to the person with your decision — worth adding when you reject, so they know why.": "Quelques mots facultatifs envoyés à la personne avec votre décision — utiles quand vous refusez, pour qu'elle sache pourquoi.",
  "Optional. A record of the total agreed with this person, checked against how it is split across the leave types below. It does not limit any request.": "Facultatif. Le total convenu avec cette personne, comparé à sa répartition entre les types de congé ci-dessous. Il ne limite aucune demande.",
  "Or a name": "Ou un nom",
  "Or add a new guest": "Ou ajouter un nouvel invité",
  "Or bring in a whole month at once: File → Download → Microsoft Excel (.xlsx), and upload that. Every day tab goes onto the daily stock sheet, oldest first.": "Ou importez un mois entier d'un coup : Fichier → Télécharger → Microsoft Excel (.xlsx), puis importez ce fichier. Chaque onglet de jour est ajouté à la fiche de stock journalière, du plus ancien au plus récent.",
  "Or pick the workbook straight from Google Drive →": "Ou choisissez le classeur directement dans Google Drive →",
  "Or set the monthly rate directly": "Ou définir directement le tarif mensuel",
  "Or, send {firstName} a link to do this themselves": "Ou envoyez à {firstName} un lien pour le faire lui-même",
