  "Policies, licences, certificates and forms you may see. Press a document to open it here.": "Les politiques, licences, certificats et formulaires que vous pouvez consulter. Appuyez sur un document pour l'ouvrir ici.",
  "Policies, licences, permits, certificates and forms in one place. Give a document an expiry date and the OS warns you before it runs out; when it is renewed, upload the new version. Press a number to show only those.": "Politiques, licences, permis, certificats et formulaires au même endroit. Donnez une date d'expiration à un document et l'OS vous prévient avant l'échéance ; une fois renouvelé, téléversez la nouvelle version. Appuyez sur un chiffre pour n'afficher que ceux-là.",
