  "Purchase requests": "Demandes d'achat",
  "Purchase requests from across the company and where each one is: asked, approved, ordered, received. Decide with a note, then record the order and the delivery. Press a number to show only those.": "Les demandes d'achat de toute l'entreprise et leur étape : demandée, approuvée, commandée, reçue. Décidez avec une note, puis enregistrez la commande et la livraison. Appuyez sur un chiffre pour n'afficher que celles-là.",
  "Purchase requests that arrived, at their real cost, raw bamboo batches and restaurant supplies delivered. Supplier payments aren't recorded, so a purchase counts as paid when it is received.": "Les demandes d'achat reçues, à leur coût réel, les lots de bambou brut et les fournitures livrées aux restaurants. Les paiements fournisseurs ne sont pas enregistrés : un achat compte comme payé à sa réception.",
