  "Turned down": "Refusées",
  "Turned down, cancelled, or it passed its valid-until date without an answer (expired). It can be reopened as a draft to update the prices.": "Refusé, annulé, ou sa date de validité est passée sans réponse (expiré). Il peut être rouvert en brouillon pour mettre à jour les prix.",
  "Turned down, or ran past its valid-until date.": "Refusé, ou dépassé sa date de validité.",
  "Turns the offer into a draft booking on the unit. Activating the booking is what puts the tenant in.": "Transforme l'offre en réservation brouillon. C'est l'activation de la réservation qui installe le locataire.",
