  "Who sells": "Qui vend",
  "Who supplies our bamboo and materials, where they are, what they quoted, whether their bamboo meets spec, and what they have delivered. Press a number to show only those.": "Qui nous fournit le bambou et les matériaux, où ils sont, ce qu'ils ont proposé, si leur bambou est conforme et ce qu'ils ont livré. Appuyez sur un chiffre pour n'afficher que ceux-là.",
  "Who supplies what, and how to reach them.": "Qui fournit quoi, et comment les joindre.",
