  "You already have a face on file — continuing replaces it.": "Un visage est déjà enregistré pour vous — continuer le remplacera.",
  "You are almost out of {types}.": "Vous avez presque épuisé vos {types}.",
  "you are told when it arrives": "vous êtes prévenu à l'arrivée",
  "you are up to date": "vous êtes à jour",
  "You are up to date: nothing new since you last looked.": "Vous êtes à jour : rien de nouveau depuis votre dernière visite.",
  "You can also upload the monthly summary tab (e.g. \"2026 Sept\"): it brings in each day's figure as stock history, and its latest day as the stock.": "Vous pouvez aussi importer l'onglet récapitulatif mensuel (par ex. « 2026 Sept ») : il ajoute le chiffre de chaque jour à l'historique du stock, et celui du dernier jour devient le stock.",
  "You can generate a share link or send this by WhatsApp once it's created — open it from the list and click Preview.": "Vous pourrez générer un lien de partage ou l'envoyer par WhatsApp une fois créé — ouvrez-le depuis la liste et cliquez sur Aperçu.",
  "You can see the sheet; people who manage the stock fill it in.": "Vous pouvez consulter la fiche ; les personnes qui gèrent le stock la remplissent.",
  "You can see these settings but your role can't change them. Ask someone with Company settings access.": "Vous pouvez voir ces paramètres mais votre rôle ne permet pas de les modifier. Demandez à une personne ayant accès aux paramètres de l'entreprise.",
  "You can send up to {n} files at a time.": "Vous pouvez envoyer jusqu'à {n} fichiers à la fois.",
  "You can't change your own roles.": "Vous ne pouvez pas changer vos propres rôles.",
  "You clocked in at {clockIn} on {date} but didn't clock out, so the system clocked you out automatically at {clockOut}, {hours} hours later.": "Vous avez pointé l'entrée à {clockIn} le {date} sans pointer la sortie ; le système a donc pointé votre sortie automatiquement à {clockOut}, {hours} heures plus tard.",
  "You confirmed you have read this": "Vous avez confirmé l'avoir lue",
  "You have {n} days of {type} left this year.": "Il vous reste {n} jours de {type} cette année.",
  "You have {n} tasks due today.": "Vous avez {n} tâches à rendre aujourd'hui.",
  "You have changes that aren't saved yet.": "Vous avez des modifications non enregistrées.",
  "You haven't clocked in yet today. Your shift started at {time}.": "Vous n'avez pas encore pointé aujourd'hui. Votre poste a commencé à {time}.",
  "You still have {n} days of paid leave this year. Plan them before 31 December.": "Il vous reste {n} jours de congé payé cette année. Planifiez-les avant le 31 décembre.",
  "You will have {left} of {total} days left.": "Il vous restera {left} jours sur {total}.",
  "You worked {time} this shift": "Vous avez travaillé {time} sur ce service",
  "you're all caught up": "tout est à jour",
  "You're all caught up": "Vous êtes à jour",
  "You're all caught up. Requests from the people you're responsible for will appear here.": "Tout est à jour. Les demandes des personnes dont vous êtes responsable apparaîtront ici.",
  "You're all set! Face recognition is now active for your clock-ins. You can close this page.": "Tout est prêt ! La reconnaissance faciale est désormais active pour vos pointages. Vous pouvez fermer cette page.",
  "You've been clocked in since {time} on {date}. Clock out if you have finished.": "Vous êtes pointé depuis {time} le {date}. Pointez la sortie si vous avez terminé.",
  "Your {category} claim of {amount} was rejected.": "Votre demande {category} de {amount} a été refusée.",
  "Your {category} claim was rejected: “{note}”": "Votre demande {category} a été refusée : « {note} »",
  "Your {type} from {dates} is approved.": "Votre {type} du {dates} est approuvé.",
  "Your {type} request for {date} is waiting for a decision.": "Votre demande de {type} pour le {date} attend une décision.",
  "Your {type} request was turned down: \"{note}\"": "Votre demande de {type} a été refusée : « {note} »",
  "Your account is protected": "Votre compte est protégé",
  "Your account was created (or reset) with a temporary password. Choose your own before you carry on — only you should know it.": "Votre compte a été créé (ou réinitialisé) avec un mot de passe temporaire. Choisissez le vôtre avant de continuer — vous seul devez le connaître.",
  "Your approvals": "Vos approbations",
  "Your backup codes": "Vos codes de secours",
  "Your balance for this type is set when you send the request.": "Votre solde pour ce type est établi à l'envoi de la demande.",
  "Your clock, and the last two weeks.": "Votre pointage, et les deux dernières semaines.",
  "Your conversations": "Vos conversations",
  "Your conversations are kept for you only. Pick one to carry on where you left off.": "Vos conversations sont gardées pour vous seul. Choisissez-en une pour reprendre là où vous vous étiez arrêté.",
  "Your conversations will be kept here.": "Vos conversations seront gardées ici.",
  "Your day, your leave, your work and your pay, in one place. Only you see this page. Press a number to go to it.": "Votre journée, vos congés, votre travail et votre paie, au même endroit. Vous seul voyez cette page. Appuyez sur un chiffre pour y aller.",
  "Your days in {year}": "Vos jours en {year}",
  "Your entitlement this year minus what you have used, for paid leave types. Requests still waiting are not taken off until approved.": "Vos droits de l'année moins ce que vous avez pris, pour les congés payés. Les demandes en attente ne sont déduites qu'une fois approuvées.",
  "Your expense claims, purchase requests and payslips.": "Vos notes de frais, demandes d'achat et fiches de paie.",
  "Your last shift was not clocked out": "Votre dernier poste n'a pas été pointé en sortie",
  "your manager is notified": "votre responsable est prévenu",
  "Your manager is notified, and you are told when it is decided, ordered and received.": "Votre responsable est prévenu, et vous êtes informé quand la demande est décidée, commandée et reçue.",
  "Your mobile number:": "Votre numéro de mobile :",
  "Your new password": "Votre nouveau mot de passe",
  "your open tasks": "vos tâches en cours",
  "Your own claim": "Votre propre demande",
  "Your password is changed. Signing you in…": "Votre mot de passe est changé. Connexion en cours…",
  "Your payslips show here once payroll approves a pay run.": "Vos fiches de paie apparaissent ici dès que la paie approuve un cycle.",
  "Your photo": "Votre photo",
  "Your question": "Votre question",
  "Your questions and its answers, kept so you can carry on later. Only you can open them. Deleting one doesn't undo changes made through it.": "Vos questions et ses réponses, gardées pour que vous puissiez reprendre plus tard. Vous seul pouvez les ouvrir. En supprimer une n'annule pas les modifications faites par son biais.",
  "Your rate — 1 {currency} = ? {base}": "Votre taux — 1 {currency} = ? {base}",
  "Your record and how you sign in. Ask HR if something here is wrong.": "Votre fiche et votre façon de vous connecter. Demandez aux RH si quelque chose est faux.",
  "Your request for {dates} is waiting for your manager.": "Votre demande pour {dates} attend votre responsable.",
  "your requests": "vos demandes",
  "Your role can see this bill but not send reminders for it.": "Votre rôle peut voir cette facture mais pas envoyer de rappels pour elle.",
  "Your role can see this booking but not contact the tenant about it.": "Votre rôle peut voir cette réservation mais pas contacter le locataire à ce sujet.",
  "Your role doesn't allow it to change anything for you. It can still look things up.": "Votre rôle ne lui permet rien de modifier pour vous. Il peut toujours consulter.",
  "Your shift": "Votre service",
